			Nodes: nodes, Relations: relations,
		})
	if err != nil {
		t.Fatal(err)
	}
	var teamID shoal.ID
	for _, node := range result.Nodes {
		if string(node.Key) == value.Team.ID {
			teamID = node.ID
		}
	}
	now := time.Date(2026, 9, 7, 12, 0, 0, 0, time.UTC)
