	if len(overview.People) != 2 || len(overview.Agents) != 2 ||
		len(overview.WorkItems) != workItemCount ||
		len(overview.Activities) != activityDays {
		t.Fatalf("overview = people:%d agents:%d items:%d activities:%d %#v",
			len(overview.People), len(overview.Agents), len(overview.WorkItems),
			len(overview.Activities), overview.Activities)
	}
}

func (s *provisionServerState) heartbeatAgent(
	writer http.ResponseWriter, request *http.Request,
) {
	parts := strings.Split(request.URL.Path, "/")
	id := parts[len(parts)-2]
	s.mu.Lock()
	s.agents[id]++
	generation := s.agents[id]
	s.mu.Unlock()
	writeTestJSON(writer, http.StatusOK, map[string]any{
		"id": id, "generation": generation,
		"lease_expires_at": time.Now().UTC().Add(time.Hour),
	})
}

func graphMaterializeEndpoint(service Service) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		provider, ok := service.(GraphMaterializationProvider)
		if !ok {
			writeError(writer, shoal.NewError(
				shoal.ErrorUnavailable, "graph materialization is unavailable"))
			return
		}
		var input GraphMaterializeRequest
		if err := decodeRequest(writer, request, &input); err != nil {
			writeError(writer, shoal.NewError(
				shoal.ErrorInvalidArgument, err.Error()))
			return
		}
		result, err := provider.MaterializeGraph(request.Context(), input)
		if err != nil {
			writeError(writer, err)
			return
		}
		writeResponse(writer, http.StatusOK, result)
	}
}

func validateGraphKind(name, value string) error {
	if strings.TrimSpace(value) == "" || !utf8.ValidString(value) {
		return shoal.NewError(
			shoal.ErrorInvalidArgument, name+" must be valid nonblank UTF-8")
	}
	return shoal.ValidateSemanticString(name, value)
}

// MaterializeGraph publishes one bounded, immutable graph fixture under the
// exact trusted source and policy selected for the caller.
func (c *Client) MaterializeGraph(
	ctx context.Context,
	request explorer.GraphMaterializationRequest,
) (explorer.GraphMaterializationResult, error) {
	backend, ok := c.base.(graphMaterializationBackend)
	if !ok {
		return explorer.GraphMaterializationResult{}, shoal.NewError(
			shoal.ErrorUnavailable, "graph materialization is unavailable")
	}
	decision, guard, now, err := c.begin(ctx, auth.OperationGraphMaterialize)
	if err != nil {
		return explorer.GraphMaterializationResult{}, err
	}
	rule, err := c.selectGraphMaterializationRule(ctx, decision, now)
	if err != nil {
		return explorer.GraphMaterializationResult{}, err
	}
	if err := decision.Authorize(
		auth.OperationGraphMaterialize,
		auth.ResourceRequest{
			AuthorizationDomain: decision.AuthorizationDomain(),
			SourceID:            request.SourceID, PolicyID: request.PolicyID,
		},
		now,
	); err != nil {
		return explorer.GraphMaterializationResult{}, authorizationDenied()
	}
	components := rule.components()
	if len(components) != 1 ||
		!bytes.Equal(components[0].SourceID(), request.SourceID) ||
		!bytes.Equal(components[0].GrantPolicyID(), request.PolicyID) {
		return explorer.GraphMaterializationResult{}, authorizationDenied()
	}
	request.IdentityNamespace = auth.DigestBytes(
		"explorer-graph-materialization-identity-v1",
		logicalRuleBytes(rule.keys),
	).Bytes()

	c.mutationMu.Lock()
	defer c.mutationMu.Unlock()
	lease, err := c.policyStore.AcquireMutation(ctx)
	if err != nil {
		return explorer.GraphMaterializationResult{},
			policyCatalogWriteError(ctx, err)
	}
	defer lease.Release()
	if err := guard.Check(ctx); err != nil {
		return explorer.GraphMaterializationResult{}, err
	}
	planned, err := backend.PlanGraphMaterialization(ctx, request)
	if err != nil {
		return explorer.GraphMaterializationResult{}, directBaseError(err)
	}
	nodeRegistration := NodeRegistration{
		DocumentID: planned.MaterializationID,
		RevisionID: planned.MutationID,
		Rule:       mustCloneRule(rule),
	}
	for _, node := range planned.GraphNodes {
		nodeRegistration.Node = node
		if err := c.policyStore.PutNode(
			ctx, node.ID, nodeRegistration,
		); err != nil {
			return explorer.GraphMaterializationResult{},
				policyCatalogWriteError(ctx, err)
		}
	}
	for _, edge := range planned.GraphEdges {
		if err := c.policyStore.PutEdge(ctx, EdgeRegistration{
			Edge: edge, DocumentID: planned.MaterializationID,
			RevisionID: planned.MutationID, Rule: mustCloneRule(rule),
		}); err != nil {
			return explorer.GraphMaterializationResult{},
				policyCatalogWriteError(ctx, err)
		}
	}
	if err := guard.Check(ctx); err != nil {
		return explorer.GraphMaterializationResult{}, err
	}
	result, err := backend.CommitGraphMaterialization(ctx, planned)
	if err != nil {
		return explorer.GraphMaterializationResult{}, directBaseError(err)
	}
	if err := guard.Check(ctx); err != nil {
		return explorer.GraphMaterializationResult{},
			explorer.MarkIndeterminateCommit(err)
	}
	return result, nil
}

func writeGraphMetadataDigest(
	digest interface{ Write([]byte) (int, error) },
	metadata shoal.Metadata,
) {
	keys := make([]string, 0, len(metadata))
	for key := range metadata {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		writeGraphDigestPart(digest, []byte(key))
		writeGraphDigestPart(digest, []byte(metadata[key]))
	}
}

func buildScenario(c config) (scenario, error) {
	start, err := time.Parse(time.RFC3339, c.ScenarioStart)
	if err != nil {
		return scenario{}, err
	}
	team := map[string]any{
		"id": c.Team.ID, "name": c.Team.Name,
		"person_ids": []string{c.Users[0].PersonID, c.Users[1].PersonID},
		"agent_ids":  []string{c.Users[0].Agent.ID, c.Users[1].Agent.ID},
	}
	workItems := makeWorkItems(c, start)
	activities := makeActivities(c, start, workItems)
	plans := make([]userPlan, len(c.Users))
	for index, user := range c.Users {
		plans[index].User = user
		person := map[string]any{
			"id": user.PersonID, "display_name": user.DisplayName,
			"team_id": c.Team.ID, "team_role": user.TeamRole,
			"oidc_subject_id":  user.OIDCSubject,
			"shoal_subject_id": user.trustedID,
		}
		agent := map[string]any{
			"id": user.Agent.ID, "name": user.Agent.Name,
			"team_id": c.Team.ID, "owner_person_id": user.PersonID,
			"owner_shoal_subject_id": user.trustedID,
			"mode":                   "simulated", "capability": user.Agent.Capability,
			"skills": append([]string(nil), user.Agent.Skills...),
		}
		files := []fixtureFile{}
		if index == 0 {
			file, err := makeFixture("shoal-demo-01-team.txt", "team", []any{team})
			if err != nil {
				return scenario{}, err
			}
			files = append(files, file)
		}
		personFile, err := makeFixture(
			fmt.Sprintf("shoal-demo-%02d-person.txt", 2+index),
			"person", []any{person})
		if err != nil {
			return scenario{}, err
		}
		agentFile, err := makeFixture(
			fmt.Sprintf("shoal-demo-%02d-agent.txt", 4+index),
			"simulated_agent", []any{agent})
		if err != nil {
			return scenario{}, err
		}
		files = append(files, personFile, agentFile)
		itemRecords := make([]any, 0, len(workItems))
		for itemIndex, item := range workItems {
			if itemIndex%len(c.Users) == index {
				itemRecords = append(itemRecords, item)
			}
		}
		itemFile, err := makeFixture(
			fmt.Sprintf("shoal-demo-%02d-work-items.txt", 6+index),
			"work_item", itemRecords)
		if err != nil {
			return scenario{}, err
		}
		activityRecords := make([]any, 0, len(activities))
		for activityIndex, activity := range activities {
			if activityIndex%len(c.Users) == index {
				activityRecords = append(activityRecords, activity)
			}
		}
		activityFile, err := makeFixture(
			fmt.Sprintf("shoal-demo-%02d-activity.txt", 8+index),
			"activity", activityRecords)
		if err != nil {
			return scenario{}, err
		}
		files = append(files, itemFile, activityFile)
		plans[index].Files = files
	}
	nodes, relations := makeGraph(c, workItems, activities)
	return scenario{Plans: plans, Nodes: nodes, Relations: relations}, nil
}

