	}

	harness.registerAgent(t, "alice")
	before := harness.teamOverview(t, "alice", aliceWorkspace)

	aliceDispatch := harness.callFleetTool(
		t, "alice", aliceWorkspace, aliceSession, 8,
		mcp.FleetDispatchToolName, "alice-queued", false)
	aliceInvoke := harness.callFleetTool(
		t, "alice", aliceWorkspace, aliceSession, 9,
		mcp.FleetInvokeToolName, "alice-completed", true)
	bobDispatch := harness.callFleetTool(
		t, "bob", bobWorkspace, bobSession, 10,
		mcp.FleetDispatchToolName, "bob-queued", false)

	if aliceDispatch.Action.RequestID == aliceInvoke.Action.RequestID {
		t.Fatalf(
			"Alice MCP calls reused request ID %q",
			aliceDispatch.Action.RequestID)
	}
	if aliceDispatch.Action.CorrelationID == "" ||
		aliceDispatch.Action.CorrelationID !=
			aliceInvoke.Action.CorrelationID {
		t.Fatalf(
			"Alice session correlations = %q, %q",
			aliceDispatch.Action.CorrelationID,
			aliceInvoke.Action.CorrelationID)
	}
	if aliceDispatch.Action.CorrelationID ==
		bobDispatch.Action.CorrelationID {
		t.Fatalf(
			"cross-user session correlation was shared: %q",
			aliceDispatch.Action.CorrelationID)
	}
	for _, action := range []fleet.ActionRecord{
		aliceDispatch.Action, aliceInvoke.Action, bobDispatch.Action,
	} {
		if strings.HasPrefix(
			string(action.CorrelationID), "caller-correlation-") {
			t.Fatalf("caller-authored correlation was trusted: %q",
				action.CorrelationID)
		}
	}
	if aliceInvoke.Action.State != fleet.DispatchSucceeded {
		t.Fatalf("simulated invoke state = %q", aliceInvoke.Action.State)
	}

	after := harness.teamOverview(t, "bob", bobWorkspace)
	if after.Metrics.ActionStates.Succeeded !=
		before.Metrics.ActionStates.Succeeded+1 ||
		after.Metrics.ActionStates.Queued !=
			before.Metrics.ActionStates.Queued+2 {
		t.Fatalf(
			"team metrics did not reflect Fleet lifecycle: before=%#v after=%#v",
			before.Metrics.ActionStates, after.Metrics.ActionStates)
	}
	if !overviewHasFleetEvidence(after, "alice-completed") {
		t.Fatalf("team overview omitted completed action evidence: %#v",
			after.Activities)
	}

	provenance := harness.provenance(t, "alice", aliceWorkspace)
	if !hasVisibleInteraction(provenance, "bob", true) {
		t.Fatalf(
			"Alice did not see Bob's authorized evidence-backed interaction: %#v",
			provenance.Interactions)
	}
	beforeOutside := provenanceIDs(provenance)
	outside := filepath.Join(root, "outside-mcp")
	if err := os.Mkdir(outside, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(
		filepath.Join(outside, "editor-save.txt"),
		[]byte("outside MCP editor fixture"), 0o600,
	); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(
		filepath.Join(outside, "terminal-command.txt"),
		[]byte("go test ./..."), 0o600,
	); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(
		filepath.Join(outside, "git-status.txt"),
		[]byte("working tree clean"), 0o600,
	); err != nil {
		t.Fatal(err)
	}
	afterOutside := provenanceIDs(
		harness.provenance(t, "alice", aliceWorkspace))
	if !reflect.DeepEqual(beforeOutside, afterOutside) {
		t.Fatalf(
			"outside-MCP fixture actions changed durable interactions:\nbefore=%v\nafter=%v",
			beforeOutside, afterOutside)
	}

	harness.close()
	harness = newDemoAcceptanceHarness(t, root)
	if status := harness.getWorkspaceStatus(
		t, "alice", aliceWorkspace,
	); status != http.StatusOK {
		t.Fatalf("Alice workspace after restart status = %d", status)
	}
	if status := harness.getWorkspaceStatus(
		t, "bob", bobWorkspace,
	); status != http.StatusOK {
		t.Fatalf("Bob workspace after restart status = %d", status)
	}
	restartedSession := harness.initializeMCP(
		t, "alice", aliceWorkspace, 11)
	harness.initializeNotification(
		t, "alice", aliceWorkspace, restartedSession)
	restartedRetrieve := harness.callTool(
		t, "alice", aliceWorkspace, restartedSession, 12,
		mcp.ToolDocuments, map[string]any{})
	var documents webapi.DocumentsResponse
	if err := json.Unmarshal(
		restartedRetrieve.StructuredContent, &documents,
	); err != nil {
		t.Fatal(err)
	}
	if len(documents.Documents) < 2 {
		t.Fatalf(
			"restart retrieval returned %d results",
			len(documents.Documents))
	}
	restartedOverview := harness.teamOverview(
		t, "alice", aliceWorkspace)
	if restartedOverview.Metrics.ActionStates !=
		after.Metrics.ActionStates {
		t.Fatalf(
			"Fleet metrics changed across restart: before=%#v after=%#v",
			after.Metrics.ActionStates,
			restartedOverview.Metrics.ActionStates)
	}
	restartedProvenance := harness.provenance(
		t, "alice", aliceWorkspace)
	if len(restartedProvenance.Interactions) <=
		len(provenance.Interactions) ||
		!hasVisibleInteraction(restartedProvenance, "bob", true) {
		t.Fatalf(
			"durable provenance after restart = %#v",
			restartedProvenance.Interactions)
	}
}

func (h *demoAcceptanceHarness) rawMCP(
	t *testing.T,
	token string,
	workspace string,
	session string,
	body string,
) *http.Response {
	t.Helper()
	request, err := http.NewRequest(
		http.MethodPost, h.server.URL+"/mcp", strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Authorization", "Bearer "+token)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("Accept", "application/json, text/event-stream")
	request.Header.Set(webapi.WorkspaceIDHeader, workspace)
	if session != "" {
		request.Header.Set(mcp.SessionHeader, session)
		request.Header.Set(
			mcp.ProtocolVersionHeader, mcp.ProtocolVersion)
	}
	response, err := h.server.Client().Do(request)
	if err != nil {
		t.Fatal(err)
	}
	return response
}

func newDemoAcceptanceHarness(
	t *testing.T,
	root string,
) *demoAcceptanceHarness {
	t.Helper()
	authority := auth.NewAuthority()
	opened, err := openService(context.Background(), serviceConfig{
		backend: "embedded", data: filepath.Join(root, "corpus"),
		policyDir: filepath.Join(root, "policy"),
		resolver:  authority.Resolver(), clock: time.Now,
		executors: configuredFleetExecutors{
			"demo": demoAcceptanceExecutor{},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	harness := &demoAcceptanceHarness{
		root: root, authority: authority, opened: opened,
	}
	authenticator := webapi.AuthenticatorFunc(func(
		request *http.Request,
	) (auth.Decision, error) {
		token := strings.TrimPrefix(
			request.Header.Get("Authorization"), "Bearer ")
		if token != "alice" && token != "bob" {
			return auth.Decision{}, shoal.NewError(
				shoal.ErrorUnauthorized, "unknown test token")
		}
		return demoAcceptanceDecision(
			t, shoal.ID(token),
			shoal.ID(token+"-request-"+
				strconv.FormatUint(harness.requests.Add(1), 10)),
			shoal.ID("caller-correlation-"+token),
		), nil
	})

	httpServer := httptest.NewUnstartedServer(nil)
	handler, err := webapi.NewAuthenticatedHandler(
		opened.service, authenticator, authority.Binder(),
		httpServer.Listener.Addr().String())
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if err := handler.SetWorkspaceSettingsProvider(
		opened.settings); err != nil {
		opened.close()
		t.Fatal(err)
	}
	provenance, err := webapi.NewInteractionService(opened.client)
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if err := handler.SetInteractionProvider(provenance); err != nil {
		opened.close()
		t.Fatal(err)
	}
	interactionTools, err := mcp.NewInteractionTools(provenance)
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	fleetTools, err := mcp.NewFleetDispatchTools(
		opened.fleetDispatch, authority.Resolver())
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	mcpServer, err := mcp.NewServer(mcp.Config{
		Service: opened.service, Authority: authority,
		Decisions:       mcp.DecisionProviderFunc(authority.Resolver().Resolve),
		InteractionSink: opened.client, Snapshots: opened.client,
		WorkspaceSettings: opened.settings,
		OptionalTools:     append(interactionTools, fleetTools...),
		ServerInfo: mcp.Implementation{
			Name: "demo-acceptance", Version: "1",
		},
	})
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	mcpHandler, err := mcp.NewHTTPHandler(mcp.HTTPConfig{
		Server: mcpServer,
		AllowedOrigins: []string{
			"http://" + httpServer.Listener.Addr().String(),
		},
		RequireWorkspaceSettings: true,
	})
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if err := handler.MountAuthenticated("/mcp", mcpHandler); err != nil {
		opened.close()
		t.Fatal(err)
	}
	fleetHandler, err := webapi.NewFleetHandler(
		opened.fleetRegistry, opened.fleetDispatch)
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if err := handler.MountAuthenticated(
		webapi.FleetRoutePrefix, fleetHandler,
	); err != nil {
		opened.close()
		t.Fatal(err)
	}
	boundDispatch, ok := opened.fleetDispatch.(*boundFleetDispatch)
	if !ok {
		opened.close()
		t.Fatal("embedded Fleet dispatch binding is unavailable")
	}
	overview, err := teamoverview.NewService(teamoverview.Config{
		Graph: demoTeamGraph{}, Agents: opened.fleetRegistry,
		Actions: boundDispatch.service, Interactions: opened.client,
		Resolver: authority.Resolver(), Clock: time.Now,
	})
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	teamHandler, err := webapi.NewTeamOverviewHandler(overview)
	if err != nil {
		opened.close()
		t.Fatal(err)
	}
	if err := handler.MountAuthenticated(
		webapi.TeamOverviewRoute, teamHandler,
	); err != nil {
		opened.close()
		t.Fatal(err)
	}
	httpServer.Config.Handler = handler
	httpServer.Start()
	harness.server = httpServer
	return harness
}

func (h *demoAcceptanceHarness) callTool(
	t *testing.T,
	token string,
	workspace string,
	session string,
	id int,
	name string,
	arguments any,
) mcp.ToolResult {
	t.Helper()
	rawArguments, err := json.Marshal(arguments)
	if err != nil {
		t.Fatal(err)
	}
	params, err := json.Marshal(mcp.CallToolParams{
		Name: name, Arguments: rawArguments,
	})
	if err != nil {
		t.Fatal(err)
	}
	response := h.rawMCP(
		t, token, workspace, session,
		`{"jsonrpc":"2.0","id":`+strconv.Itoa(id)+
			`,"method":"tools/call","params":`+string(params)+`}`)
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK {
		t.Fatalf("%s HTTP status = %d: %s",
			name, response.StatusCode, body)
	}
	var envelope struct {
		Result mcp.ToolResult `json:"result"`
		Error  *mcp.Error     `json:"error"`
	}
	if err := json.Unmarshal(body, &envelope); err != nil {
		t.Fatal(err)
	}
	if envelope.Error != nil || envelope.Result.IsError {
		t.Fatalf("%s failed: %s", name, body)
	}
	return envelope.Result
}

func (demoAcceptanceExecutor) Execute(
	ctx context.Context,
	invocation fleet.Invocation,
) (fleet.ExecutionResult, error) {
	if err := ctx.Err(); err != nil {
		return fleet.ExecutionResult{}, err
	}
	return fleet.ExecutionResult{
		Output: append(json.RawMessage(nil), invocation.Input...),
	}, nil
}

func openService(
	ctx context.Context,
	config serviceConfig,
) (openedService, error) {
	closed := openedService{close: func() {}}
	switch config.backend {
	case "embedded":
		runtimeConfig := explorercoord.Config{
			Directory: config.data,
			Domain:    workspacePublicationDomain,
			Owner:     workspaceRuntimeOwner,
			Authority: transaction.Authority{
				Generation:          1,
				Fence:               1,
				Holder:              workspaceRuntimeOwner,
				Mode:                coordination.WriterModeEmbeddedPrimary,
				RetentionGeneration: 1,
				HistoryFloor:        1,
			},
			Clock: config.clock,
		}
		explorerfleetevents.ConfigureHostedRuntime(&runtimeConfig)
		embedded, err := explorercoord.OpenExplorer(
			runtimeConfig, explorer.Options{Embedder: config.embedder})
		if err != nil {
			return closed, err
		}
		corpus := embedded.Explorer
		// The policy catalog is durable and lives in its own directory, not a
		// subdirectory of the corpus: the corpus engine treats every
		// subdirectory as a table, so nesting the store there would corrupt
		// table discovery. A caller that sets only data keeps the legacy
		// sibling layout; -state-dir/-policy-dir place both under one mount.
		policyDir := config.policyDir
		if policyDir == "" {
			policyDir = policyStoreDir(config.data)
		}
		store, err := authorized.OpenDurablePolicyStore(policyDir)
		if err != nil {
			embedded.Close()
			return closed, err
		}
		// A non-empty corpus paired with an empty policy catalog is the
		// signature of a lost or unmounted policy volume: the documents
		// survived but every authorization registration is gone. Refuse rather
		// than serve a silently under-authorized workspace. The development
		// backfill is the sanctioned way to (re)register a pre-durability
		// corpus, so this guard applies only in production (backfill == nil),
		// where the two situations are otherwise indistinguishable.
		if config.backfill == nil {
			if err := refuseSplitBrainStateDirectory(
				ctx, corpus, store, config.data, policyDir); err != nil {
				store.Close()
				embedded.Close()
				return closed, err
			}
		}
		generationReader := config.generationReader
		if isNilFleetDependency(generationReader) {
			generationReader = fixedGenerationReader{
				domain:     workspaceAuthorizationDomain,
				generation: workspacePolicyGeneration,
			}
		}
		client, err := authorizedClient(
			corpus, store, config.resolver, generationReader,
			config.clock, config.mosaic)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		if err := corpus.EnsureInteractionSink(ctx); err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		interactionRecorder, err := interaction.NewRecorder(
			ctx, fleetInteractionSink{durable: corpus, authorized: client})
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		if err := interactionRecorder.SetClock(config.clock); err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetLifecycleRecorder, err := explorerfleet.NewLifecycleRecorderWithReader(
			fleetInteractionSink{durable: corpus, authorized: client}, corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		executors := config.executors
		if executors == nil {
			executors = configuredFleetExecutors{}
		}
		snapshots, err := explorerfleet.NewInteractionSnapshotProvider(corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetRegistry, err := explorerfleet.Compose(
			embedded.Runtime, config.resolver, fleetLifecycleRecorder, snapshots,
			executors, nil, config.clock)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		cursorKey, err := explorerfleetevents.LoadOrCreateCursorKey(ctx, corpus)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetEvents, actionEvents, err :=
			explorerfleetevents.ComposeWithPublisherAndReader(
				embedded.Runtime, workspacePublicationDomain, config.resolver,
				generationReader, func(operation auth.Operation) interaction.ResultSink {
					if sink := client.FleetActionInteractionSink(operation); sink != nil {
						return sink
					}
					return client
				}, corpus, snapshots, fleetRegistry, cursorKey, config.clock,
			)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		actionRecorder, err := explorerfleet.NewActionRecorderWithSnapshots(
			interactionRecorder, snapshots)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		fleetDispatch, err := explorerfleet.ComposeDispatch(
			embedded.Runtime, fleetRegistry, config.resolver, actionRecorder,
			actionEvents, nil, config.clock,
		)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		teamOverview, err := teamoverview.NewService(teamoverview.Config{
			Graph: client, Agents: fleetRegistry, Actions: fleetDispatch,
			Interactions: client, Resolver: config.resolver, Clock: config.clock,
		})
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		boundFleetDispatch, err := newBoundFleetDispatch(
			fleetDispatch, config.resolver)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		boundFleetRegistry, err := newBoundFleetRegistry(
			fleetRegistry, config.resolver)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		// The development-only backfill migrates a corpus whose documents were
		// ingested before the policy catalog was durable: their authorization
		// registrations are absent until re-registered once. A failure here is
		// fatal by design: the workspace must not serve a corpus it could not
		// finish authorizing.
		backfilled, err := config.backfill.run(ctx, client)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		service, err := webapi.NewEmbeddedService(client)
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		if config.ontology != nil {
			// This call is load-bearing; TestOntologyProposalLifecycleUsesStartedEmbeddedWorkspace
			// pins that startup wires -ontology-file into the real EmbeddedService
			// path used by proposal creation, not only into an injected test double.
			if err := service.SetOntologyVersion(*config.ontology); err != nil {
				store.Close()
				embedded.Close()
				return closed, err
			}
		}
		settingsStore, err := workspace.NewDurableStoreWithEngine(
			embedded.Runtime.EmbeddedEngine())
		if err != nil {
			store.Close()
			embedded.Close()
			return closed, err
		}
		choices, err := webapi.NewGovernedOntologyChoices(service)
		if err != nil {
			settingsStore.Close()
			store.Close()
			embedded.Close()
			return closed, err
		}
		settingsProvider, err := workspace.NewProvider(
			settingsStore,
			workspace.ProviderOptions{
				Resolver:         config.resolver,
				GenerationReader: generationReader,
				OntologyChoices:  choices,
				Clock:            config.clock,
			},
		)
		if err != nil {
			settingsStore.Close()
			store.Close()
			embedded.Close()
			return closed, err
		}
		return openedService{
			service:       service,
			settings:      settingsProvider,
			fleetRegistry: boundFleetRegistry,
			fleetDispatch: boundFleetDispatch,
			fleetEvents:   fleetEvents,
			teamOverview:  teamOverview,
			client:        client,
			backfilled:    backfilled,
			close: func() {
				settingsStore.Close()
				store.Close()
				embedded.Close()
			},
		}, nil
	case "remote":
		// The remote backend forwards workspace calls to an upstream Explorer
		// web API over HTTP and has no way to carry the caller's decision
		// across that hop: webapi.RemoteService is a workspace service, not an
		// explorer.Client, so authorized.Client cannot wrap it, and no
		// on-the-wire representation of auth.Decision exists yet. Serving it
		// would mean authenticating at this edge and then calling upstream
		// with no identity at all. Refuse rather than leave that path open.
		return closed, fmt.Errorf(
			"backend remote is unavailable: forwarding the caller's " +
				"authorization decision to an upstream Explorer is not " +
				"implemented, so the upstream call would carry no identity " +
				"(see issue #278, edge identity)")
	default:
		return closed, fmt.Errorf("unknown backend %q", config.backend)
	}
}

