  add(name) {
    const values = new Set(this.element.className.split(/\s+/).filter(Boolean));
    values.add(name);
    this.element.className = [...values].join(" ");
  }
}
class Element {
  constructor(tag, id = "") {
    this.tagName = tag.toUpperCase();
    this.id = id;
    this.children = [];
    this.parent = null;
