	ctx context.Context, request Request,
) (Response, error) {
	now := s.clock().UTC()
	normalized, cursor, err := normalizeRequest(request, now)
	if err != nil {
		return Response{}, err
	}
	decision, err := s.resolver.Resolve(ctx)
	if err != nil {
		return Response{}, err
	}
