func appendUniqueID(values []shoal.ID, value shoal.ID) []shoal.ID {
	for _, present := range values {
		if present == value {
			return values
		}
	}
	return append(values, value)
}

func containsByteValue(values [][]byte, value []byte) bool {
	if len(values) == 0 {
		return false
	}
	index := sort.Search(len(values), func(i int) bool {
		return bytes.Compare(values[i], value) >= 0
	})
	return index < len(values) && bytes.Equal(values[index], value)
}

func parseRoster(
	request Request, nodes []graph.Node, edges []graph.Edge,
) (parsedRoster, error) {
	if len(nodes) > int(MaxGraphNodes) || len(edges) > int(MaxGraphEdges) {
		return parsedRoster{}, shoal.NewError(
			shoal.ErrorInvalidArgument,
			"team graph response exceeds the overview bound",
		)
	}
	result := parsedRoster{
		nodeIDs: make(map[shoal.ID]struct{}, len(nodes)),
		edgeIDs: make(map[shoal.ID]struct{}, len(edges)),
	}
	nodesByID := make(map[shoal.ID]graph.Node, len(nodes))
	for _, node := range nodes {
		nodesByID[node.ID] = node
	}
	teamNode, ok := nodesByID[request.TeamID]
	if !ok || teamNode.Kind != KindTeam {
		return parsedRoster{}, auth.ObjectNotFound()
	}
	result.team = Team{
		ID: teamNode.ID, Name: firstProperty(
			teamNode, PropertyName, PropertyTitle),
		NodeID: teamNode.ID, SourceID: encodeBytes(request.SourceID),
		PolicyID: encodeBytes(request.PolicyID),
	}
	result.nodeIDs[teamNode.ID] = struct{}{}
	members := make(map[shoal.ID]struct{})
	for _, edge := range edges {
		if edge.Type == RelationMemberOf && edge.To == request.TeamID {
			members[edge.From] = struct{}{}
			result.edgeIDs[edge.ID] = struct{}{}
		}
	}
	people := make(map[shoal.ID]*Person)
	agents := make(map[shoal.ID]*Agent)
	items := make(map[shoal.ID]*WorkItem)
	for _, node := range nodes {
		if _, member := members[node.ID]; !member {
			continue
		}
		result.nodeIDs[node.ID] = struct{}{}
		name := firstProperty(node, PropertyName, PropertyTitle)
		switch node.Kind {
		case KindPerson:
			person := Person{
				ID: node.ID, Name: name, NodeID: node.ID,
				SubjectID: shoal.ID(node.Properties[PropertySubjectID]),
			}
			people[node.ID] = &person
		case KindAgent:
			id := shoal.ID(node.Properties[PropertyAgentID])
			if id == "" {
				id = node.ID
			}
			agent := Agent{ID: id, Name: name, NodeID: node.ID}
			agents[id] = &agent
		case KindWorkItem:
			item := WorkItem{
				ID: node.ID, Title: name,
				Status: node.Properties[PropertyStatus],
				NodeID: node.ID, AssignedTo: []shoal.ID{}, BlockedBy: []shoal.ID{},
			}
			items[node.ID] = &item
		case KindActivity:
			recordedAt, err := time.Parse(
				time.RFC3339Nano, node.Properties[PropertyRecordedAt])
			if err != nil {
				continue
			}
			manual, _ := strconv.ParseBool(node.Properties[PropertyManual])
			result.activities = append(result.activities, graphActivity{
				id: node.ID, recordedAt: recordedAt.UTC(),
				actorID:   shoal.ID(node.Properties[PropertyActorID]),
				operation: node.Properties[PropertyOperation], manual: manual,
			})
		}
	}
	for _, edge := range edges {
		_, fromMember := members[edge.From]
		_, toMember := members[edge.To]
		if edge.Type == RelationMemberOf {
			continue
		}
		if !fromMember || !toMember {
			continue
		}
		result.edgeIDs[edge.ID] = struct{}{}
		switch edge.Type {
		case RelationAssignedTo:
			if item := items[edge.From]; item != nil {
				item.AssignedTo = appendUniqueID(item.AssignedTo, edge.To)
			}
		case RelationBlockedBy:
			if item := items[edge.From]; item != nil {
				if _, ok := items[edge.To]; ok {
					item.BlockedBy = appendUniqueID(item.BlockedBy, edge.To)
				}
			}
		}
	}
	for _, value := range people {
		result.people = append(result.people, *value)
	}
	for _, value := range agents {
		result.agents = append(result.agents, *value)
	}
	for _, value := range items {
		sortIDs(value.AssignedTo)
		sortIDs(value.BlockedBy)
		result.workItems = append(result.workItems, *value)
	}
	sort.Slice(result.people, func(i, j int) bool { return result.people[i].ID < result.people[j].ID })
	sort.Slice(result.agents, func(i, j int) bool { return result.agents[i].ID < result.agents[j].ID })
	sort.Slice(result.workItems, func(i, j int) bool { return result.workItems[i].ID < result.workItems[j].ID })
	return result, nil
}

func (h *HTTPHandler) servePost(
	writer http.ResponseWriter,
	request *http.Request,
	decision auth.Decision,
	fingerprint auth.Fingerprint,
	workspace workspaceBinding,
	hasWorkspace bool,
) {
	if !acceptsMediaType(request.Header.Values("Accept"), "application/json") ||
		!acceptsMediaType(request.Header.Values("Accept"), "text/event-stream") {
		h.writeHTTPError(writer, http.StatusNotAcceptable,
			newError(codeInvalidRequest,
				"Accept must include application/json and text/event-stream"))
		return
	}
	mediaType, _, err := mime.ParseMediaType(request.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		h.writeHTTPError(writer, http.StatusUnsupportedMediaType,
			newError(codeInvalidRequest, "Content-Type must be application/json"))
		return
	}
	raw, err := readHTTPMessage(writer, request)
	if err != nil {
		h.writeHTTPError(writer, http.StatusBadRequest,
			newError(codeInvalidRequest, "invalid request body"))
		return
	}
	message, failure := decodeRequest(raw)
	if failure != nil {
		id, _ := protocolFailureID(raw, failure)
		h.writeHTTPErrorResponse(writer, http.StatusBadRequest,
			newErrorResponse(id, failure))
		return
	}

	sessionID := singleHeader(request.Header, SessionHeader)
	if message.Method == "initialize" {
		if len(request.Header.Values(SessionHeader)) != 0 ||
			sessionID != "" || message.isNotification() {
			h.writeHTTPError(writer, http.StatusBadRequest,
				newError(codeInvalidRequest, "invalid initialization request"))
			return
		}
		versionValues := request.Header.Values(ProtocolVersionHeader)
		if len(versionValues) > 1 {
			h.writeHTTPError(writer, http.StatusBadRequest,
				newError(codeInvalidRequest, "unsupported protocol version"))
			return
		}
		if version := singleHeader(request.Header, ProtocolVersionHeader); version != "" && version != ProtocolVersion {
			h.writeHTTPError(writer, http.StatusBadRequest,
				newError(codeInvalidRequest, "unsupported protocol version"))
			return
		}
		h.initializeHTTP(
			writer, request, message, decision, fingerprint,
			workspace, hasWorkspace)
		return
	}

	session, ok := h.authorizedSession(
		writer, request, fingerprint, workspace, hasWorkspace)
	if !ok {
		return
	}
	if message.Method == "notifications/cancelled" && message.isNotification() {
		session.cancel(message.Params)
		writer.WriteHeader(http.StatusAccepted)
		return
	}
	if !h.revalidate(
		request.Context(), fingerprint, workspace, hasWorkspace) {
		writer.Header().Set("WWW-Authenticate", "Bearer")
		h.writeHTTPError(writer, http.StatusUnauthorized,
			newError(codeInvalidRequest, "authorization expired"))
		return
	}
	mutating := session.dispatcher.requestMutates(message)
	ctx, err := session.dispatcher.bindHTTPSessionDecision(
		request.Context(), decision, session.correlation)
	if err != nil {
		writer.Header().Set("WWW-Authenticate", "Bearer")
		h.writeHTTPError(writer, http.StatusUnauthorized,
			newError(codeInvalidRequest, "authentication required"))
		return
	}
	var cancel context.CancelFunc
	if !message.isNotification() {
		ctx, cancel, err = session.register(ctx, message.ID)
		if errors.Is(err, errHTTPSessionClosed) {
			h.writeHTTPError(writer, http.StatusNotFound,
				newError(codeInvalidRequest, "MCP session was not found"))
			return
		}
		if err != nil {
			h.writeHTTPError(writer, http.StatusConflict,
				newError(codeInvalidRequest, "request ID is already active"))
			return
		}
		defer session.unregister(message.ID)
		defer cancel()
	}
	response := session.dispatcher.handle(ctx, message)
	if message.isNotification() {
		writer.WriteHeader(http.StatusAccepted)
		return
	}
	if response == nil {
		h.writeHTTPError(writer, http.StatusInternalServerError,
			newError(codeInternalError, "missing response"))
		return
	}
	if !mutating && !h.revalidate(
		request.Context(), fingerprint, workspace, hasWorkspace) {
		writer.Header().Set("WWW-Authenticate", "Bearer")
		h.writeHTTPError(writer, http.StatusUnauthorized,
			newError(codeInvalidRequest, "authorization expired"))
		return
	}
	h.writeBoundedHTTPResponse(
		writer, http.StatusOK, *response,
		httpResponseLimit(workspace, hasWorkspace),
		message.Method == "tools/call",
	)
}

