func run(
	ctx context.Context,
	args []string,
	output io.Writer,
	getenv func(string) string,
	client *http.Client,
) error {
	flags := flag.NewFlagSet("shoal-demo-seed", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	configPath := flags.String("config", "", "path to the demo scenario JSON")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *configPath == "" {
		return errors.New("-config is required")
	}
	if flags.NArg() != 0 {
		return errors.New("unexpected positional arguments")
	}
	loaded, err := loadConfig(*configPath)
	if err != nil {
		return err
	}
	generated, err := buildScenario(loaded)
	if err != nil {
		return err
	}
	if client == nil || getenv == nil {
		return errors.New("HTTP client and environment reader are required")
	}
	summary, err := (&provisioner{client: client, getenv: getenv}).provision(
		ctx, loaded, generated)
	if err != nil {
		return err
	}
	encoder := json.NewEncoder(output)
	encoder.SetIndent("", "  ")
	return encoder.Encode(summary)
}

func TestBuildScenarioIsDeterministicAndComplete(t *testing.T) {
	value := validConfig("https://shoal.example.test")
	if err := value.validate(); err != nil {
		t.Fatal(err)
	}
	first, err := buildScenario(value)
	if err != nil {
		t.Fatal(err)
	}
	second, err := buildScenario(value)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatal("scenario generation is not deterministic")
	}
	if len(first.Plans) != 2 {
		t.Fatalf("plans = %d", len(first.Plans))
	}
	kinds := make(map[string]int)
	workItems := 0
	activities := make(map[string]struct{})
	actors := make(map[string]struct{})
	for _, plan := range first.Plans {
		for _, file := range plan.Files {
			var envelope struct {
				Schema  string            `json:"schema"`
				Kind    string            `json:"kind"`
				Records []json.RawMessage `json:"records"`
			}
			if err := json.Unmarshal(file.Content, &envelope); err != nil {
				t.Fatalf("decode %s: %v", file.Name, err)
			}
			if envelope.Schema != scenarioSchema {
				t.Fatalf("%s schema = %q", file.Name, envelope.Schema)
			}
			kinds[envelope.Kind] += len(envelope.Records)
			switch envelope.Kind {
			case "work_item":
				workItems += len(envelope.Records)
			case "activity":
				for _, raw := range envelope.Records {
					var activity struct {
						OccurredAt string `json:"occurred_at"`
					}
					if err := json.Unmarshal(raw, &activity); err != nil {
						t.Fatal(err)
					}
					activities[activity.OccurredAt[:10]] = struct{}{}
					var actor struct {
						ActorID string `json:"actor_id"`
					}
					if err := json.Unmarshal(raw, &actor); err != nil {
						t.Fatal(err)
					}
					actors[actor.ActorID] = struct{}{}
				}
			}
		}
	}
	if kinds["team"] != 1 || kinds["person"] != 2 ||
		kinds["simulated_agent"] != 2 {
		t.Fatalf("fixture kinds = %#v", kinds)
	}
	if workItems != workItemCount {
		t.Fatalf("work items = %d", workItems)
	}
	if len(activities) != activityDays {
		t.Fatalf("activity dates = %d", len(activities))
	}
	for _, actor := range []string{
		"person-a", "person-b", "agent-planning", "agent-delivery",
	} {
		if _, ok := actors[actor]; !ok {
			t.Fatalf("activity does not include actor %q: %#v", actor, actors)
		}
	}
}

func loopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	address := net.ParseIP(host)
	return address != nil && address.IsLoopback()
}

func makeActivities(
	c config,
	start time.Time,
	workItems []map[string]any,
) []map[string]any {
	events := []string{
		"work_item.created", "agent.run.completed", "work_item.started",
		"review.completed", "agent.run.failed", "work_item.completed",
		"work_item.updated",
	}
	activities := make([]map[string]any, 0, activityDays)
	for day := 0; day < activityDays; day++ {
		owner := day % len(c.Users)
		actorKind := "person"
		actorID := c.Users[owner].PersonID
		if (day/len(c.Users))%2 == 1 {
			actorKind = "simulated_agent"
			actorID = c.Users[owner].Agent.ID
		}
		outcome := "success"
		if events[day%len(events)] == "agent.run.failed" {
			outcome = "failure"
		}
		item := workItems[day%len(workItems)]
		activities = append(activities, map[string]any{
			"id":      fmt.Sprintf("demo-activity-%02d", day+1),
			"team_id": c.Team.ID,
			"occurred_at": start.AddDate(0, 0, day).
				Add(time.Duration(9+day%4) * time.Hour).Format(time.RFC3339),
			"actor_kind": actorKind, "actor_id": actorID,
			"event": events[day%len(events)], "outcome": outcome,
			"work_item_id": item["id"],
			"evidence_id":  fmt.Sprintf("demo-evidence-activity-%02d", day+1),
		})
	}
	return activities
}

func makeFixture(name, kind string, records []any) (fixtureFile, error) {
	envelope := struct {
		Schema  string `json:"schema"`
		Kind    string `json:"kind"`
		Records []any  `json:"records"`
	}{
		Schema: scenarioSchema, Kind: kind, Records: records,
	}
	content, err := json.MarshalIndent(envelope, "", "  ")
	if err != nil {
		return fixtureFile{}, err
	}
	content = append(content, '\n')
	return fixtureFile{Name: name, Content: content}, nil
}

