func (p *provisioner) provision(
	ctx context.Context,
	c config,
	generated scenario,
) (provisionSummary, error) {
	summary := provisionSummary{
		TeamID: c.Team.ID, WorkItems: workItemCount, ActivityDays: activityDays,
		UserSummaries: make([]userSummary, 0, len(generated.Plans)),
	}
	for _, plan := range generated.Plans {
		token := strings.TrimSpace(p.getenv(plan.User.TokenEnv))
		if token == "" {
			return provisionSummary{}, fmt.Errorf(
				"environment variable %s is required", plan.User.TokenEnv)
		}
		if err := p.verifyIdentity(ctx, c.BaseURL, token, plan.User); err != nil {
			return provisionSummary{}, err
		}
		if err := p.putWorkspaceSettings(
			ctx, c.BaseURL, token, plan.User, c.Workspace); err != nil {
			return provisionSummary{}, err
		}
		dispositions, err := p.ingest(
			ctx, c.BaseURL, token, plan.User.workspaceKey, plan.Files)
		if err != nil {
			return provisionSummary{}, err
		}
		summary.UserSummaries = append(summary.UserSummaries, userSummary{
			PersonID: plan.User.PersonID, WorkspaceID: plan.User.WorkspaceID,
			WorkspaceHeader: plan.User.workspaceKey, Files: dispositions,
		})
	}
	return summary, nil
}

func (p *provisioner) putWorkspaceSettings(
	ctx context.Context,
	baseURL, token string,
	user userConfig,
	settings workspaceConfig,
) error {
	payload := struct {
		ExpectedRevision uint64 `json:"expected_revision"`
		MutationID       string `json:"mutation_id"`
		Settings         struct {
			Budgets struct {
				RetrievalTopK uint32 `json:"retrieval_top_k"`
				GraphDepth    uint32 `json:"graph_depth"`
				GraphFanout   uint32 `json:"graph_fanout"`
				GraphNodes    uint32 `json:"graph_nodes"`
				OutputBytes   uint64 `json:"output_bytes"`
			} `json:"budgets"`
		} `json:"settings"`
	}{
		ExpectedRevision: 0,
		MutationID:       workspaceMutationID(user.WorkspaceID),
	}
	payload.Settings.Budgets.RetrievalTopK = settings.RetrievalTopK
	payload.Settings.Budgets.GraphDepth = settings.GraphDepth
	payload.Settings.Budgets.GraphFanout = settings.GraphFanout
	payload.Settings.Budgets.GraphNodes = settings.GraphNodes
	payload.Settings.Budgets.OutputBytes = settings.OutputBytes
	body, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	request, err := http.NewRequestWithContext(
		ctx, http.MethodPut,
		baseURL+"/api/v1/workspaces/"+user.workspaceKey+"/settings",
		bytes.NewReader(body),
	)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+token)
	request.Header.Set("Accept", "application/json")
	request.Header.Set("Content-Type", "application/json")
	response, err := p.client.Do(request)
	if err != nil {
		return fmt.Errorf("provision %s workspace settings: %w", user.PersonID, err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK &&
		response.StatusCode != http.StatusCreated {
		return fmt.Errorf(
			"provision %s workspace settings: %w",
			user.PersonID, requireStatus(response, http.StatusOK),
		)
	}
	return nil
}

func loadConfig(path string) (config, error) {
	file, err := os.Open(path)
	if err != nil {
		return config{}, fmt.Errorf("open config: %w", err)
	}
	defer file.Close()
	decoder := json.NewDecoder(file)
	decoder.DisallowUnknownFields()
	var value config
	if err := decoder.Decode(&value); err != nil {
		return config{}, fmt.Errorf("decode config: %w", err)
	}
	if err := requireJSONEOF(decoder); err != nil {
		return config{}, err
	}
	if err := value.validate(); err != nil {
		return config{}, err
	}
	return value, nil
}

func workspaceInitializeMeta(ctx context.Context) map[string]any {
	binding, ok, err := effectiveWorkspaceBinding(ctx)
	if err != nil || !ok {
		return nil
	}
	if binding.settingsID == "" {
		return map[string]any{
			"shoal.workspace": map[string]any{
				"id": binding.headerValue(),
			},
		}
	}
	return map[string]any{
		"shoal.workspace": map[string]any{
			"id": binding.headerValue(),
			"settings_id": base64.RawURLEncoding.EncodeToString(
				[]byte(binding.settingsID)),
			"revision":         binding.revision,
			"cache_dimensions": cloneCacheDimensions(binding.cacheDimensions),
			"limits": map[string]any{
				"retrieval_top_k": binding.limits.RetrievalTopK,
				"graph_depth":     binding.limits.GraphDepth,
				"graph_fanout":    binding.limits.GraphFanout,
				"graph_nodes":     binding.limits.GraphNodes,
				"output_bytes":    binding.limits.OutputBytes,
			},
		},
	}
}

func TestRemoteServiceAllowsScopedVectorWhenGlobalCapabilityIsUnavailable(t *testing.T) {
	retrieveCalled := false
	now := time.Date(2026, time.August, 29, 12, 0, 0, 0, time.UTC)
	embeddingSpace, err := retrieval.EmbeddingSpaceIdentityID("space-v3")
	if err != nil {
		t.Fatal(err)
	}
	embeddingSpaceSet, err := retrieval.EmbeddingSpaceSetID(embeddingSpace)
	if err != nil {
		t.Fatal(err)
	}
	upstream := httptest.NewServer(http.HandlerFunc(func(
		writer http.ResponseWriter,
		request *http.Request,
	) {
		switch {
		case request.Method == http.MethodGet && request.URL.Path == "/api/v1/meta":
			writeJSON(t, writer, webapi.MetadataResponse{
				MaxPageSize: webapi.MaxPageSize,
				MaxTopK:     webapi.MaxTopK,
				MaxDepth:    webapi.MaxDepth,
				MaxFanout:   webapi.MaxFanout,
				MaxNodes:    webapi.MaxNodes,
				Capabilities: webapi.Capabilities{
					Documents: true, Document: true, Retrieve: true,
					Neighborhood: true, Path: true, Vector: false,
				},
			})
		case request.Method == http.MethodPost && request.URL.Path == "/api/v1/retrieve":
			retrieveCalled = true
			writeJSON(t, writer, webapi.RetrievalResponse{
				Snapshot: webapi.Snapshot{
					ID: "snapshot", AsOf: now, Frontier: 1,
				},
				Retrieval: retrieval.Response{
					EmbeddingSpaceID:  embeddingSpaceSet,
					EmbeddingSpaceIDs: []shoal.ID{embeddingSpace},
				},
			})
		default:
			http.NotFound(writer, request)
		}
	}))
	defer upstream.Close()
	service, err := webapi.NewRemoteService(upstream.URL, upstream.Client())
	if err != nil {
		t.Fatal(err)
	}
	response, err := service.Retrieve(context.Background(), webapi.RetrievalRequest{
		Query: retrieval.Request{
			Text:  "query",
			Modes: []retrieval.Mode{retrieval.ModeVector},
			Scope: retrieval.Scope{DocumentIDs: []shoal.ID{
				"document",
			}},
		},
	})
	if err != nil {
		t.Fatalf("scoped vector retrieve: %v", err)
	}
	if response.Retrieval.EmbeddingSpaceID != embeddingSpaceSet ||
		len(response.Retrieval.EmbeddingSpaceIDs) != 1 ||
		response.Retrieval.EmbeddingSpaceIDs[0] != embeddingSpace {
		t.Fatalf("remote embedding space = %q",
			response.Retrieval.EmbeddingSpaceID)
	}
	if !retrieveCalled {
		t.Fatal("scoped vector request did not reach remote endpoint")
	}
}

