func requestIDKey(id json.RawMessage) (string, bool) {
	if !validRequestID(id) || len(id) == 0 {
		return "", false
	}
	if id[0] == '"' {
		var value string
		if json.Unmarshal(id, &value) != nil {
			return "", false
		}
		return "s:" + value, true
	}
	value, ok := new(big.Rat).SetString(string(id))
	if !ok || !value.IsInt() {
		return "", false
	}
	return "n:" + value.Num().String(), true
}

