	}
	if metadataBytes(metadata) > limits.MaxProvenanceBytes {
		return nil, invalid("context metadata and provenance exceed the byte bound")
	}
	if err := shoal.ValidateMetadata("context metadata", metadata); err != nil {
		return nil, err
	}
	return metadata, nil
}

