func (r chatContextReader) Neighborhood(ctx context.Context, request explorer.NeighborhoodRequest) (explorer.Neighborhood, error) {
	if request.Depth > r.limits.GraphDepth {
		return explorer.Neighborhood{}, chatInvalid("graph expansion exceeds workspace depth")
	}
	page, err := r.client.BoundedNeighborhood(ctx, explorer.BoundedNeighborhoodRequest{
		NodeIDs: request.NodeIDs, Depth: request.Depth, EdgeTypes: request.EdgeTypes,
		Fanout: r.limits.GraphFanout, MaxNodes: r.limits.GraphNodes,
		MaxScannedEdges: r.limits.GraphNodes * r.limits.GraphFanout,
		Direction:       explorer.GraphDirectionOutgoing,
	})
	if err != nil {
		return explorer.Neighborhood{}, err
	}
	if page.Truncated || page.Continuation || page.NextAfterEdgeID != "" {
		return explorer.Neighborhood{}, shoal.NewError(shoal.ErrorUnavailable, "chat evidence graph is incomplete within workspace limits")
	}
	return page.Neighborhood, nil
}

// NewActionTransition snapshots the exact event-producing state of one
// committed dispatch transition.
func NewActionTransition(
	id []byte, kind string, record ActionRecord,
) (ActionTransition, error) {
	switch kind {
	case "action.enqueued":
	case "action.claimed":
	case "action.completed":
	case "action.failed":
	case "action.canceled":
	default:
		return ActionTransition{}, shoal.NewError(
			shoal.ErrorInvalidArgument, "fleet action transition kind is invalid")
	}
	if actionEventKind(record) != kind {
		return ActionTransition{}, shoal.NewError(
			shoal.ErrorInvalidArgument,
			"fleet action transition kind does not match action state")
	}
	result := ActionTransition{
		ID: append([]byte(nil), id...), Kind: kind, Record: cloneActionRecord(record),
	}
	if err := result.Validate(); err != nil {
		return ActionTransition{}, err
	}
	return result, nil
}

func cloneSubscription(subscription Subscription) Subscription {
	result := subscription
	result.ID = cloneBytes(subscription.ID)
	result.Filter = cloneFilter(subscription.Filter)
	return result
}

func decodeFleetOpaqueIDs(values []string) ([][]byte, error) {
	result := make([][]byte, len(values))
	for i := range values {
		decoded, err := decodeFleetOpaqueID(values[i])
		if err != nil {
			return nil, err
		}
		result[i] = decoded
	}
	return result, nil
}

