	}
}

func digest(tag string, parts ...[]byte) []byte {
	hash := sha256.New()
	writeDigestField(hash, []byte(tag))
	for _, part := range parts {
		writeDigestField(hash, part)
	}
	return hash.Sum(nil)
}

