// DerivedAssertions returns canonical derived assertions by assertion ID from
// the current graph. Missing or non-derived IDs are omitted so callers can
// fail closed without learning whether another assertion kind exists.
func (e *Explorer) DerivedAssertions(
	ctx context.Context, ids []shoal.ID,
) (map[shoal.ID]ontology.Assertion, error) {
	if err := contextError(ctx); err != nil {
		return nil, err
	}
	if err := e.acquireReadWithGraph(); err != nil {
		return nil, err
	}
	defer e.mu.RUnlock()
	result := make(map[shoal.ID]ontology.Assertion, len(ids))
	for _, id := range ids {
		if err := shoal.ValidateRequiredID(
			"derived assertion ID", id); err != nil {
			return nil, err
		}
		assertion, ok := e.graphAssertions[id]
		if !ok || assertion.ID() != id ||
			assertion.Origin() != ontology.AssertionDerived {
			continue
		}
		result[id] = assertion
	}
	return result, nil
}

func assertionHydrationPayloadBytes(state assertionHydration) int {
	total := assertionPayloadBytes(state.assertion)
	for _, edgeID := range state.edgeIDs {
		total += assertionReferencePayloadBytes(
			state.assertion.ID(), edgeID, state.assertion.Origin())
	}
	return total
}

func (e *Explorer) currentInteractionVisibilityLocked(
	record persistedInteraction,
) (string, error) {
	if !record.EdgeProvenanceComplete {
		return "", shoal.NewError(
			shoal.ErrorUnavailable,
			"interaction source-edge provenance is incomplete",
		)
	}
	references, err := record.Session.EvidenceReferences()
	if err != nil {
		return "", err
	}
	for _, reference := range references {
		if err := e.validateEvidenceReferenceLocked(reference); err != nil {
			return "", err
		}
	}
	touched := interaction.TouchedNodes(record.Nodes, record.Edges)
	nodeIDs := append(
		append([]shoal.ID(nil), touched.RetrievedNodeIDs...),
		touched.CitedNodeIDs...,
	)
	nodeVisibility, err := e.conjoinNodeVisibilityLocked(nodeIDs)
	if err != nil {
		return "", err
	}
	resolveEdge := e.edgeVisibilityResolverLocked()
	sets := [][]string{nodeVisibility, record.Session.RequiredVisibility}
	for _, edgeID := range record.Session.TouchedEdgeIDs() {
		labels, err := resolveEdge(edgeID)
		if err != nil {
			return "", err
		}
		sets = append(sets, labels)
	}
	visibility, err := interaction.Conjoin(sets...)
	if err != nil {
		return "", err
	}
	return interaction.Expression(visibility), nil
}

