			ColumnVisibility: append([]byte(nil), cell.visibility...),
			Timestamp:        &timestamp,
			Kind:             engine.ConditionAbsent,
		}
		if cell.delete {
			mutation.Delete(cell.family, cell.qualifier, cell.visibility, cell.timestamp)
