	}
	if len(results) != 1 {
		return fmt.Errorf("%w: physical conditional result count is invalid", transaction.ErrInternal)
	}
	if results[0] {
		return nil
	}
	for index := range cells {
		got, found, readErr := p.readExact(ctx, cells[index])
