// PruneCommitted verifies every target against its immutable committed proof,
// writes epoch-stamped physical tombstones, retires each target entity guard,
// and advances a caller-owned local floor in one existing transaction.
//
// Callers page candidates with ScanCommitted and pass at most MaxPruneTargets.
// The shared allocator HistoryFloor is neither read as the requested floor nor
// mutated by this API.
func (r *Runtime) PruneCommitted(
	ctx context.Context,
	request PruneCommittedRequest,
) (PruneCommittedResult, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if r.closed {
		return PruneCommittedResult{}, transaction.ErrUnavailable
	}
	if len(request.Targets) == 0 || len(request.Targets) > MaxPruneTargets {
		return PruneCommittedResult{}, errors.Join(
			transaction.ErrInvalid,
			errors.New("prune target count is outside its bound"),
		)
	}
	txn, err := DeriveTXN(r.domain, request.Operation, request.Token)
	if err != nil {
		return PruneCommittedResult{}, err
	}
	if stored, loadErr := r.intents.Load(ctx, txn); loadErr == nil {
		matches, matchErr := r.pruneIntentMatchesRequest(
			ctx,
			stored.Intent,
			request,
		)
		if matchErr != nil {
			return PruneCommittedResult{}, matchErr
		}
		if !matches {
			return PruneCommittedResult{}, transaction.ErrConflict
		}
		result, publishErr := r.publishLocked(ctx, Request{
			Intent: stored.Intent, Owner: request.Owner,
			LeaseUntil: request.LeaseUntil,
		})
		if publishErr != nil {
			return PruneCommittedResult{}, publishErr
		}
		return PruneCommittedResult{
			Result: result,
			Pruned: len(request.Targets),
		}, nil
	} else if !errors.Is(loadErr, transaction.ErrNotFound) {
		return PruneCommittedResult{}, loadErr
	}
	intent, err := r.buildPruneIntentLocked(ctx, request)
	if err != nil {
		return PruneCommittedResult{}, err
	}
	result, err := r.publishLocked(ctx, Request{
		Intent: intent, Owner: request.Owner,
		LeaseUntil: request.LeaseUntil,
	})
	if err != nil {
		return PruneCommittedResult{}, err
	}
	return PruneCommittedResult{
		Result: result,
		Pruned: len(request.Targets),
	}, nil
}

func (r *Runtime) selectCommittedVersion(
	ctx context.Context,
	table string,
	versions []physicalVersion,
	frontier coordination.Epoch,
	proofs map[coordination.Epoch]publicationProof,
) (CommittedCell, bool, error) {
	for index := 0; index < len(versions); {
		timestamp := versions[index].key.Timestamp
		end := index + 1
		for end < len(versions) && versions[end].key.Timestamp == timestamp {
			end++
		}
		epoch := coordination.Epoch(timestamp)
		if epoch > 0 && epoch <= frontier {
			proof, err := r.proofForEpoch(ctx, epoch, proofs)
			if err != nil {
				return CommittedCell{}, false, err
			}
			if proof.committed {
				deleted := versions[index].key.Deleted
				value := versions[index].value
				for duplicate := index + 1; duplicate < end; duplicate++ {
					if versions[duplicate].key.Deleted != deleted {
						return CommittedCell{}, false, fmt.Errorf(
							"%w: physical deletion state disagrees at table %q row %x family %x qualifier %x visibility %x timestamp %d",
							transaction.ErrInternal,
							table,
							versions[index].key.Row,
							versions[index].key.ColumnFamily,
							versions[index].key.ColumnQualifier,
							versions[index].key.ColumnVisibility,
							timestamp,
						)
					}
					if !versions[duplicate].key.Deleted &&
						!bytes.Equal(value, versions[duplicate].value) {
						return CommittedCell{}, false, fmt.Errorf(
							"%w: physical versions disagree at one timestamp",
							transaction.ErrInternal,
						)
					}
				}
				version := versions[index]
				if !planContainsEpochCell(proof.plan, table, epoch, version) {
					return CommittedCell{}, false, fmt.Errorf(
						"%w: committed physical cell is absent from its durable intent",
						transaction.ErrInternal,
					)
				}
				if deleted {
					return CommittedCell{}, false, nil
				}
				return CommittedCell{
					Cell: allocator.Cell{
						Coordinate: allocator.Coordinate{
							Row:        append([]byte(nil), version.key.Row...),
							Family:     append([]byte(nil), version.key.ColumnFamily...),
							Qualifier:  append([]byte(nil), version.key.ColumnQualifier...),
							Visibility: append([]byte(nil), version.key.ColumnVisibility...),
						},
						Value:     append([]byte(nil), version.value...),
						Timestamp: version.key.Timestamp,
					},
					TXN:           append(coordination.TXN(nil), proof.txn...),
					LogicalDigest: proof.digest,
					Epoch:         epoch,
				}, true, nil
			}
		}
		index = end
	}
	return CommittedCell{}, false, nil
}

